'use client';
import { useEffect, useState, type ReactNode } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useTween } from '../lib/hooks';
import { Icon, type IconName } from '../lib/icons';
import { enter, Fold, Swap } from '../lib/motion';
import '../designme.css';
import './proposal-card.css';

export type ProposalTone = 'ok' | 'warn' | 'bad';

/** One side of the change: a swatch, its value and a tag, like #C9CFD8 with "2.1 : 1" */
export interface ProposalValue {
  /** Any CSS colour, shown in the swatch */
  color: string;
  /** Like "#C9CFD8" */
  label: string;
  /** A short tag after the value, like a contrast ratio */
  badge?: string;
  /** Colours the tag. The current value defaults to bad, the options to ok */
  tone?: ProposalTone;
}

/** A change the agent can make. The first one is its suggestion, the others show under "other options" */
export interface ProposalOption extends ProposalValue {
  /** Like "Suggested" or "Darker" */
  name: string;
  /** The quiet line beside it in the list, like "Balanced with the primary" */
  description?: string;
  /** How sure the agent is, 0 to 100 */
  confidence: number;
}

export type ProposalStatus = 'open' | 'accepted' | 'dismissed';

export interface ProposalCardProps {
  /** What the agent wants to change */
  title: ReactNode;
  /** Where, like "Pricing, frame 2 of 3" */
  subtitle?: ReactNode;
  /** The icon in the orange tile. Defaults to a wand */
  icon?: IconName;
  /** How it is now */
  from: ProposalValue;
  /** The changes on offer, the agent's pick first */
  options: ProposalOption[];
  /** Index of the option shown as the change. Leave it out to let the list pick it */
  value?: number;
  /** Defaults to 0, the agent's pick */
  defaultValue?: number;
  onValueChange?: (index: number) => void;
  /** Whether the other options are listed. Leave it out to let their toggle open them */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** open, accepted or dismissed. Leave it out to let Accept, Not now and Undo move it */
  status?: ProposalStatus;
  defaultStatus?: ProposalStatus;
  onStatusChange?: (status: ProposalStatus) => void;
  /** Called with the chosen option when Accept is pressed */
  onAccept?: (option: ProposalOption, index: number) => void;
  onDismiss?: () => void;
  onUndo?: () => void;
  /** Shown once accepted, like "Applied to 3 buttons" */
  acceptedLabel?: string;
  /** Shown once dismissed */
  dismissedLabel?: string;
  confidenceLabel?: string;
  /** Draws its own container (the default, as on designme.dev). Set true to sit it flat in a chat thread */
  bare?: boolean;
  className?: string;
}

const STEPS = 5;

/** A change the agent proposes, with its confidence, other options, and Accept or Not now. */
export function ProposalCard({
  title, subtitle, icon = 'wand', from, options, value, defaultValue = 0, onValueChange, open, defaultOpen = false, onOpenChange,
  status, defaultStatus = 'open', onStatusChange, onAccept, onDismiss, onUndo, acceptedLabel = 'Applied', dismissedLabel = 'Dismissed. The agent will not suggest this again.',
  confidenceLabel = 'Confidence', bare = false, className
}: ProposalCardProps) {
  const [sel, setSel] = useControllable(value, defaultValue, onValueChange);
  const [isOpen, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  const [state, setState] = useControllable(status, defaultStatus, onStatusChange);
  // the confidence fills in a moment after the card appears, then follows the chosen option
  const [ready, setReady] = useState(false);
  useEffect(() => { const t = setTimeout(() => setReady(true), 400); return () => clearTimeout(t); }, []);
  // the list only plays its entrance once someone has picked another option
  const [picked, setPicked] = useState(false);
  const opt = options[Math.max(0, Math.min(options.length - 1, sel))];
  const conf = useTween(ready && opt ? opt.confidence : 0, 700, 0);
  const others = options.map((o, i) => ({ o, i })).filter(x => x.i !== sel);

  const choose = (i: number) => { setPicked(true); setSel(i); };
  const accept = () => { setOpen(false); setState('accepted'); onAccept?.(opt, sel); };
  const dismiss = () => { setState('dismissed'); onDismiss?.(); };
  const undo = () => { setState('open'); onUndo?.(); };

  return (
    <div data-dm="" className={cx('dm-prx', !bare && 'dm-panel', className)}>
      <div className="dm-prx-h">
        <span className="dm-prx-ic"><Icon name={icon} /></span>
        <div className="dm-prx-ht"><b>{title}</b>{subtitle && <span className="dm-muted">{subtitle}</span>}</div>
      </div>
      <div className="dm-prx-diff">
        <div className="dm-prx-sw">
          <span className="dm-prx-c" style={{ background: from.color }} />
          <span className="dm-num">{from.label}</span>
          {from.badge && <span className={cx('dm-tag', 'dm-' + (from.tone ?? 'bad'))}>{from.badge}</span>}
        </div>
        <span className="dm-prx-ar"><Icon name="right" size="xs" /></span>
        {opt && (
          <div className="dm-prx-sw dm-prx-new">
            <span className="dm-prx-c" style={{ background: opt.color }} />
            <Swap className="dm-num">{opt.label}</Swap>
            {opt.badge && <span className={cx('dm-tag', 'dm-' + (opt.tone ?? 'ok'))}><Swap>{opt.badge}</Swap></span>}
          </div>
        )}
      </div>
      <div className="dm-prx-cf">
        <span className="dm-muted">{confidenceLabel}</span>
        <div className="dm-prx-seg" role="meter" aria-label={confidenceLabel} aria-valuemin={0} aria-valuemax={100} aria-valuenow={opt?.confidence ?? 0}>
          {Array.from({ length: STEPS }, (_, i) => <i key={i} className={cx(conf >= (i + 1) * 20 - 10 && 'dm-on')} />)}
        </div>
        <span className="dm-num dm-prx-pc">{Math.round(conf)}%</span>
      </div>
      {others.length > 0 && (
        <>
          <button type="button" className={cx('dm-prx-alt-t', isOpen && 'dm-open')} aria-expanded={isOpen} onClick={() => setOpen(!isOpen)}>
            <Icon name="chev-r" size="xs" /><span>{others.length} other {others.length > 1 ? 'options' : 'option'}</span>
          </button>
          <Fold open={isOpen} className="dm-prx-alt">
            <div className="dm-prx-alts" key={sel}>
              {others.map(({ o, i }, k) => (
                <button type="button" key={i} className={cx('dm-prx-a', picked && 'dm-enter')} style={picked ? enter(k * 50).style : undefined} onClick={() => choose(i)}>
                  <span className="dm-prx-c" style={{ background: o.color }} />
                  <span>{o.name}{o.badge && `, ${o.badge}`}</span>
                  {o.description && <span className="dm-d">{o.description}</span>}
                </button>
              ))}
            </div>
          </Fold>
        </>
      )}
      <div className="dm-prx-f">
        {state === 'open' ? (
          <>
            <button type="button" className="dm-pill dm-ghost dm-sm dm-prx-no" onClick={dismiss}>Not now</button>
            <button type="button" className="dm-pill dm-primary dm-sm dm-prx-ok" onClick={accept}>Accept</button>
          </>
        ) : state === 'accepted' ? (
          <>
            <span className="dm-prx-done dm-enter"><Icon name="ok" /><span>{acceptedLabel}</span></span>
            <button type="button" className="dm-pill dm-ghost dm-sm dm-prx-un dm-enter" style={enter(60).style} onClick={undo}><Icon name="undo" size="xs" />Undo</button>
          </>
        ) : (
          <>
            <span className="dm-prx-done dm-muted dm-enter" style={{ color: 'var(--dm-muted)' }}>{dismissedLabel}</span>
            <button type="button" className="dm-pill dm-ghost dm-sm dm-prx-un dm-enter" style={enter(60).style} onClick={undo}>Undo</button>
          </>
        )}
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Proposal card ---------- */
/* a suggestion posted in the chat: no container; with .panel it becomes a card, its content 16px from every edge */
.dm-prx{padding:var(--dm-s-4) 0;display:flex;flex-direction:column;gap:var(--dm-s-3);container-type:inline-size}
.dm-prx.dm-panel{padding:var(--dm-s-4)}
.dm-prx-h{display:flex;gap:10px;align-items:center}
.dm-prx-ic{width:32px;height:32px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-pp-bg);color:var(--dm-pp);display:grid;place-items:center;flex:none}
.dm-prx-ht{display:flex;flex-direction:column;min-width:0}
.dm-prx-ht b{font-weight:500;font-size:13.5px}
.dm-prx-ht span{font-size:12.5px}
.dm-prx-diff{display:flex;align-items:center;gap:var(--dm-s-2);padding:10px;border-radius:var(--dm-r-in);background:var(--dm-chip);flex-wrap:wrap}
.dm-prx-sw{display:flex;align-items:center;gap:var(--dm-s-2);font-size:12px;flex:1;min-width:0}
.dm-prx-ar{color:var(--dm-muted);display:grid}
/* too narrow for the change on one line (a phone): the new value goes under the old one, the arrow pointing down between
   them under the swatches, so nothing runs out of the box */
@container (max-width:300px){.dm-prx-diff{flex-direction:column;align-items:flex-start;gap:6px}.dm-prx-sw{flex:none}.dm-prx-ar{width:18px;justify-items:center;transform:rotate(90deg)}}
.dm-prx-c{width:18px;height:18px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));flex:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.08);transition:background .5s var(--dm-ease)}
.dm-prx-new .dm-num{transition:opacity .3s}
.dm-prx-cf{display:flex;align-items:center;gap:10px;font-size:12.5px}
.dm-prx-seg{display:flex;gap:3px;flex:1}
.dm-prx-seg i{flex:1;height:5px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-line);transition:background .4s}
/* the confidence is a meter, so its parts take the bright mark green (3:1), not the darker text green */
.dm-prx-seg i.dm-on{background:var(--dm-ok-mark)}
.dm-prx-pc{width:34px;text-align:right;color:var(--dm-fg2)}
/* the toggle's chevron sits on the content's edge, its hover box reaching out round it */
.dm-prx-alt-t{display:flex;align-items:center;gap:6px;margin:-4px -8px;padding:4px 8px;border-radius:var(--dm-r-pill);font-size:12.5px;color:var(--dm-fg2);align-self:flex-start;transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-prx-alt-t:hover{background:color-mix(in srgb,var(--dm-fg) 5%,transparent);color:var(--dm-fg)}}
.dm-prx-alt-t svg{transition:transform .4s var(--dm-ease)}
.dm-prx-alt-t.dm-open svg{transform:rotate(90deg)}
/* the other options: each row's fill is the content's width, no wider, and its swatch and value sit on the columns of the
   change above (10px and 36px in) */
/* the folded options keep no room: the fold takes back the card's gap before it, so the footer sits as far under the toggle as
   the card's other parts sit apart, and opened, the options start 16px under the toggle as before */
.dm-prx-alt{margin-top:calc(-1 * var(--dm-s-3))}
.dm-prx-alts{display:flex;flex-direction:column;gap:2px;padding-top:calc(var(--dm-s-1) + var(--dm-s-3))}
.dm-prx-a{display:flex;align-items:center;gap:var(--dm-s-2);padding:7px 10px;border-radius:var(--dm-r-in);font-size:13px;text-align:left;transition:background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-prx-a:hover{background:var(--dm-row)}}
.dm-prx-a .dm-d{margin-left:auto;font-size:12px;color:var(--dm-muted)}
/* narrow (a phone): each other option's line goes under its name, the swatch centred beside the two */
@container (max-width:300px){.dm-prx-a{display:grid;grid-template-columns:18px minmax(0,1fr);column-gap:var(--dm-s-2)}.dm-prx-a .dm-prx-c{grid-row:1/3;align-self:center}.dm-prx-a .dm-d{grid-column:2;margin-left:0}}
/* the footer sits under a hairline in Soft and Blueprint (owner, 21 and 22 Nov), 16px under the content and 16px over its
   buttons, as the card's own edges are; Clean's is a foot strip */
.dm-prx-f{display:flex;align-items:center;justify-content:flex-end;gap:6px;margin-top:var(--dm-s-1);padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.dm-prx .dm-pill:active{transform:none}
/* accepted: a neutral line with the green tick (owner, 18 Nov), and Undo */
.dm-prx-done{display:flex;align-items:center;gap:var(--dm-s-2);min-width:0;font-size:13px;color:var(--dm-fg);flex:1}
.dm-prx-done>svg{flex:none;color:var(--dm-ok-mark)}
/* Clean (owner, 19 Nov): a round card with its content 16px from every edge and an off-white foot strip, 16px under the
   options, whose buttons sit 16px from the card's edges and the strip's hairline (owner, 23 Nov); once you answer, the strip holds what
   happened (its tick on the content's 16px column, owner 22 Nov) and Undo. The head's tile is the neutral one with a hairline, as every Clean tile */
:root[data-style="clean"] .dm-prx.dm-panel,:root [data-style="clean"] .dm-prx.dm-panel,:root [data-style="clean"].dm-prx.dm-panel{padding:16px 16px 0}
:root[data-style="clean"] .dm-prx-ic,:root [data-style="clean"] .dm-prx-ic,:root [data-style="clean"].dm-prx-ic{background:var(--dm-chip);color:var(--dm-fg2);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .dm-prx-ht b,:root [data-style="clean"] .dm-prx-ht b,:root [data-style="clean"].dm-prx-ht b{line-height:20px}
:root[data-style="clean"] .dm-prx-ht span,:root [data-style="clean"] .dm-prx-ht span,:root [data-style="clean"].dm-prx-ht span{line-height:18px}
:root[data-style="clean"] .dm-prx-seg i,:root [data-style="clean"] .dm-prx-seg i,:root [data-style="clean"].dm-prx-seg i{transition:background-color var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .dm-prx-alt-t svg,:root [data-style="clean"] .dm-prx-alt-t svg,:root [data-style="clean"].dm-prx-alt-t svg{transition:transform var(--dm-t) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-prx-alt-t:hover,:root [data-style="clean"] .dm-prx-alt-t:hover,:root [data-style="clean"].dm-prx-alt-t:hover,:root[data-style="clean"] .dm-prx-a:hover,:root [data-style="clean"] .dm-prx-a:hover,:root [data-style="clean"].dm-prx-a:hover{background:var(--dm-row)}}
:root[data-style="clean"] .dm-prx.dm-panel .dm-prx-f,:root [data-style="clean"] .dm-prx.dm-panel .dm-prx-f,:root [data-style="clean"].dm-prx.dm-panel .dm-prx-f{margin:4px -16px 0;padding:var(--dm-strip-y) 16px;gap:4px;min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);border-top:1px solid var(--dm-line);background:var(--dm-strip);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
/* (a step of --dm-ok in the vivid green keeps the tick at 3:1 on the off-white strip, as Attachment tray's does) */
:root[data-style="clean"] .dm-prx.dm-panel .dm-prx-done>svg,:root [data-style="clean"] .dm-prx.dm-panel .dm-prx-done>svg,:root [data-style="clean"].dm-prx.dm-panel .dm-prx-done>svg{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
